import os,json,subprocess,shutil
from pathlib import Path
p=Path('/srv/projects/skill-universal')
out={'root_exists':p.is_dir(),'current_release':str((p/'current').resolve(strict=False)) if (p/'current').is_symlink() else None,'path_hits':[],'scanned_directories':0,'scan_complete':True}
targets=[p/'current',p/'runtimes',p/'runtime',p/'tools',p/'.runtime',p/'releases']
seen=set()
for t in targets:
 if not t.is_dir():continue
 rt=str(t.resolve())
 if rt in seen:continue
 seen.add(rt)
 for dirpath,dirs,files in os.walk(t,followlinks=False):
  out['scanned_directories']+=1
  if out['scanned_directories']>140000:
   out['scan_complete']=False;dirs[:]=[];break
  dirs[:]=[n for n in dirs if n not in ('.git','archive','cache','__pycache__','.pnpm-store','.npm')]
  for n in dirs+files:
   if 'hopper' not in n.lower():continue
   x=Path(dirpath)/n
   out['path_hits'].append({'path':str(x),'kind':'dir' if x.is_dir() else 'file' if x.is_file() else 'link' if x.is_symlink() else 'other','executable':bool(x.is_file() and os.access(x,os.X_OK))})
   if len(out['path_hits'])>=55:break
  if len(out['path_hits'])>=55:out['scan_complete']=False;break
def query(a):
 try:
  r=subprocess.run(a,capture_output=True,text=True,timeout=10)
  return {'exit':r.returncode,'stdout':r.stdout.strip()[:400]}
 except Exception as e:return {'error':type(e).__name__}
out['global_hopper_command']=shutil.which('hopper')
out['dpkg_hopper']=query(['dpkg-query','-W','hopper'])
out['global_candidate_paths']={v:{'exists':Path(v).exists(),'is_link':Path(v).is_symlink()} for v in ('/opt/hopper','/usr/bin/hopper','/usr/local/bin/hopper','/usr/share/hopper')}
print(json.dumps(out,separators=(',',':'),ensure_ascii=False))
